namespace rt=uos::rt;namespace json=uos::json;namespace client=uos::tests::helpers::responses_conformance_client;namespace fixture=uos::tests::helpers::responses_conformance_fixture;
using Fixture=std::shared_ptr<fixture::ResponsesConformanceFixture>;using Capture=client::ConformanceWireCapture;
namespace {
fixture::FixtureOptions options(){fixture::FixtureOptions value;value.captureDirectory=rt::fs::mkdtempSync(rt::path::join(rt::os::tmpdir(),"uos-responses-conformance-"));return value;}
std::string requestId(const Capture& capture){const auto value=rt::getString(capture.headers,"x-uos-request-id");ASSERT(value&&!value->empty());return std::string(*value);}
bool kind(const json::object& value,std::string_view type){return rt::getString(value,"type")==type;}
bool hasEvent(const Capture& capture,std::string_view type){return std::any_of(capture.events.begin(),capture.events.end(),[type](const auto& event){return kind(event,type);});}
bool hasMarker(const Fixture& value,std::string_view name){return std::any_of(value->journal->entries.begin(),value->journal->entries.end(),[name](const auto& entry){return entry.kind==name;});}
rt::Task<json::object> terminalFor(Fixture value,Capture capture){const auto id=requestId(capture);const auto pending=value->journal->wait([id](const auto& entry){return entry.kind=="request_terminal"&&rt::getString(entry.detail,"request_id")==id;});const auto entry=co_await pending.wait();co_return entry.detail;}
rt::Task<void> assertOneDispatchCharge(Fixture value,Capture capture,int committed){
  const auto id=requestId(capture);auto reading=value->ledger(id);const auto rows=co_await std::move(reading);const auto* request=rt::get(rows,"request");const auto* window=rt::get(rows,"window");ASSERT(request&&window);EXPECT_EQ(rt::getString(*request,"state"),std::optional<std::string_view>("dispatched"));EXPECT_EQ(rt::getNumber(*window,"committed_requests"),std::optional<double>(committed));EXPECT_EQ(rt::getNumber(*window,"reserved_requests"),std::optional<double>(0));EXPECT_EQ(rt::getString(rows,"paidFallback"),std::optional<std::string_view>("not_applicable"));
  int dispatched=0;for(const auto& entry:value->journal->entries)if(entry.kind=="quota_commit"){const auto* writes=rt::getArray(entry.detail,"writes");ASSERT(writes);for(const auto& write:*writes){const auto* key=rt::getArray(write,"key");const auto* row=rt::get(write,"value");if(key&&!key->empty()&&key->back().is_string()&&key->back().as_string()==id&&row&&rt::getString(*row,"state")=="dispatched")++dispatched;}}
  EXPECT_EQ(dispatched,1);EXPECT_EQ(std::count_if(value->terminals.begin(),value->terminals.end(),[id](const auto& terminal){return rt::getString(terminal,"request_id")==id;}),1);
}
void assertSequence(const Capture& capture){for(std::size_t index=0;index<capture.events.size();++index){const auto sequence=rt::getNumber(capture.events[index],"sequence_number");ASSERT(sequence);if(index)EXPECT_EQ(*sequence,rt::getNumber(capture.events[index-1],"sequence_number").value()+1);}}
void assertDurableReopen(const Fixture& value,const std::vector<Capture>& captures,int dispatches){
  EXPECT_EQ(rt::getString(value->storage,"mode"),std::optional<std::string_view>("file"));EXPECT_EQ(rt::getString(value->storage,"codec"),std::optional<std::string_view>("bun-jsc-v1"));const auto proof=value->verifyReopenedLedger();EXPECT_EQ(rt::getString(proof,"outcome"),std::optional<std::string_view>("verified"));EXPECT_EQ(rt::getNumber(proof,"dispatchesBefore"),std::optional<double>(dispatches));EXPECT_EQ(rt::getNumber(proof,"dispatchesAfter"),std::optional<double>(dispatches));ASSERT(rt::get(proof,"quotaCommitsBefore")&&rt::get(proof,"quotaCommitsAfter"));EXPECT_EQ(*rt::get(proof,"quotaCommitsBefore"),*rt::get(proof,"quotaCommitsAfter"));ASSERT(rt::get(proof,"after")&&rt::get(proof,"before"));EXPECT_EQ(*rt::get(proof,"after"),*rt::get(proof,"before"));const auto* rows=rt::getArray(proof,"after");ASSERT(rows&&rows->size()==captures.size());
  for(std::size_t index=0;index<rows->size();++index){const auto& row=(*rows)[index];EXPECT_EQ(rt::getString(row,"requestId"),std::optional<std::string_view>(requestId(captures[index])));const auto* request=rt::get(row,"request");const auto* window=rt::get(row,"window");ASSERT(request&&window);EXPECT_EQ(rt::getString(*request,"state"),std::optional<std::string_view>("dispatched"));EXPECT_EQ(rt::getNumber(*window,"committed_requests"),std::optional<double>(dispatches));EXPECT_EQ(rt::getNumber(*window,"reserved_requests"),std::optional<double>(0));EXPECT(rt::getString(row,"requestVersionstamp"));EXPECT(rt::getString(row,"windowVersionstamp"));}
  EXPECT_EQ(value->verifyReopenedLedger(),proof);std::vector<std::string> events;for(const auto& entry:value->journal->entries)events.push_back(entry.kind);const auto drained=std::find(events.begin(),events.end(),"transport_drained"),closed=std::find(events.begin(),events.end(),"kv_closed"),reopened=std::find(events.begin(),events.end(),"kv_reopened_verified");EXPECT(drained<closed&&closed<reopened&&reopened!=events.end());
}
rt::Task<void> finish(Fixture value,std::vector<Capture> captures){auto saving=value->save(captures);co_await std::move(saving);auto stopping=value->stop();co_await std::move(stopping);}
rt::Task<Capture> rejected(Fixture value,json::object body,std::optional<std::string> token=std::nullopt){auto opening=client::openConformanceResponse(value->endpoint,token.value_or(value->token),body);const auto response=co_await std::move(opening);const auto capture=co_await response->finished.wait();EXPECT(capture.status>=400&&capture.status<500);EXPECT(value->calls.empty());co_return capture;}
}
