  auto firstTerminalTask=terminalFor(value,captures[0]);const auto firstLog=co_await std::move(firstTerminalTask);EXPECT_EQ(rt::getString(firstLog,"delivery_outcome"),std::optional<std::string_view>("delivered"));auto firstCharge=assertOneDispatchCharge(value,captures[0],1);co_await std::move(firstCharge);
