  const auto secondTerminal=client::completedConformanceResponse(captures[1]);const auto* secondOutput=rt::getArray(secondTerminal,"output");ASSERT(secondOutput&&!secondOutput->empty());const auto* content=rt::getArray((*secondOutput)[0],"content");ASSERT(content&&!content->empty());EXPECT_EQ(rt::getString((*content)[0],"text"),std::optional<std::string_view>(client::CONFORMANCE_FINAL));const auto* secondUsage=rt::get(secondTerminal,"usage");ASSERT(secondUsage);EXPECT(!rt::get(*secondUsage,"input_tokens_details"));
  auto secondTerminalTask=terminalFor(value,captures[1]);const auto secondLog=co_await std::move(secondTerminalTask);EXPECT_EQ(rt::getString(secondLog,"delivery_outcome"),std::optional<std::string_view>("delivered"));auto secondCharge=assertOneDispatchCharge(value,captures[1],2);co_await std::move(secondCharge);EXPECT_EQ(value->calls.size(),2U);for(const auto& capture:captures)assertSequence(capture);
  const auto forwarded=rt::jsonParse(value->calls[1].body);EXPECT_EQ(rt::getString(forwarded,"model"),std::optional<std::string_view>("deepseek-flash"));EXPECT(!rt::get(forwarded,"previous_response_id"));const auto* messages=rt::getArray(forwarded,"messages");ASSERT(messages);const auto assistant=std::find_if(messages->begin(),messages->end(),[](const auto& message){return rt::getString(message,"role")=="assistant";});ASSERT(assistant!=messages->end());const auto* toolCalls=rt::getArray(*assistant,"tool_calls");ASSERT(toolCalls&&!toolCalls->empty());EXPECT_EQ(rt::getString((*toolCalls)[0],"id"),std::optional<std::string_view>(client::CONFORMANCE_CALL_ID));EXPECT_EQ(rt::getString(*rt::get((*toolCalls)[0],"function"),"arguments"),std::optional<std::string_view>(client::CONFORMANCE_ARGUMENTS));
  const auto tool=std::find_if(messages->begin(),messages->end(),[](const auto& message){return rt::getString(message,"role")=="tool";});ASSERT(tool!=messages->end());const json::object expectedTool{{"role","tool"},{"tool_call_id",client::CONFORMANCE_CALL_ID},{"content","fixture-tool-ok"}};EXPECT_EQ(*tool,json::value(expectedTool));EXPECT(std::any_of(messages->begin(),messages->end(),[](const auto& message){return rt::getString(message,"role")=="system"&&rt::includes(rt::getString(message,"content").value_or(""),"Keep the exact fixture values.");}));EXPECT_EQ(value->controller.snapshot().active,0);
